/*
 * Tests for the Pascal parameter slot convention (arch/arch.h,
 * source-nxtd).
 *
 * Generated by: Claude Opus 5.5
 *
 * Domain Pascal pushes 16-bit value parameters as 2-byte stack slots and
 * the hand-assembled routines in <sub>/sau2 .s files read them there; gcc pushes
 * 4-byte slots, the value in the low (higher-addressed) half.  The owners'
 * public headers wrap each such routine in a same-name macro that packs
 * the natural arguments into the Pascal layout.  These tests check
 *   - the packing macros put a lone word in the slot's FIRST word (the
 *     bytes a big-endian m68k stores at the lower address), a pair in
 *     push order, and a straddling longword across two slots;
 *   - the header macros route the natural call through the slot-typed
 *     function: a stub of (ML_$SPIN_UNLOCK) sees the token in
 *     ARCH_PASCAL_SLOT_WORD, (MMU_$INSTALL) sees asid:prot, (IO_$TRAP) can
 *     rebuild the handler from its two slots.
 */

#include <stdio.h>
#include <string.h>

#include "base/base.h"
#include "ml/ml.h"
#include "mmu/mmu.h"
#include "io/io.h"

int __host_intr_disable_count = 0;

static int failures;

#define ASSERT_EQ(expected, actual)                                          \
    do {                                                                     \
        unsigned long long e_ = (unsigned long long)(expected);              \
        unsigned long long a_ = (unsigned long long)(actual);                \
        if (e_ != a_) {                                                      \
            printf("  FAIL %s:%d: expected 0x%llx, got 0x%llx\n", __FILE__,  \
                   __LINE__, e_, a_);                                        \
            failures++;                                                      \
        }                                                                    \
    } while (0)

#define RUN_TEST(fn)                                                         \
    do {                                                                     \
        printf("  %s\n", #fn);                                               \
        fn();                                                                \
    } while (0)

/* The four bytes a big-endian m68k stores for a pushed gcc slot. */
static void be_bytes(uint32_t slot, uint8_t out[4])
{
    out[0] = (uint8_t)(slot >> 24);
    out[1] = (uint8_t)(slot >> 16);
    out[2] = (uint8_t)(slot >> 8);
    out[3] = (uint8_t)slot;
}

/* ---- stubs of the hand-assembled routines ------------------------------ */

static int unlock_calls;
static void *unlock_lockp;
static uint16_t unlock_token;

void (ML_$SPIN_UNLOCK)(void *lockp, uint32_t token_slot)
{
    unlock_calls++;
    unlock_lockp = lockp;
    unlock_token = ARCH_PASCAL_SLOT_WORD(token_slot);
}

static uint32_t install_ppn, install_va;
static uint16_t install_asid, install_prot;

void (MMU_$INSTALL)(uint32_t ppn, uint32_t va, uint32_t asid_prot_slot)
{
    install_ppn = ppn;
    install_va = va;
    install_asid = ARCH_PASCAL_SLOT_WORD(asid_prot_slot);
    install_prot = ARCH_PASCAL_SLOT_WORD2(asid_prot_slot);
}

static uint16_t trap_vector;
static uint32_t trap_handler_va;

void (IO_$TRAP)(uint32_t vector_handler_slot, uint32_t handler_pad_slot)
{
    trap_vector = ARCH_PASCAL_SLOT_WORD(vector_handler_slot);
    trap_handler_va = ARCH_PASCAL_SLOTS_LONG(vector_handler_slot,
                                             handler_pad_slot);
}

/* ---- tests ------------------------------------------------------------- */

/* ML_$SPIN_UNLOCK reads `move.w (8,sp),sr': the slot's first word. */
static void test_word_slot_is_first_word(void)
{
    uint8_t b[4];
    uint32_t s = ARCH_PASCAL_WORD_SLOT(0x2700);

    ASSERT_EQ(0x27000000u, s);
    be_bytes(s, b);
    ASSERT_EQ(0x27, b[0]);
    ASSERT_EQ(0x00, b[1]);
    ASSERT_EQ(0x00, b[2]);
    ASSERT_EQ(0x00, b[3]);
    ASSERT_EQ(0x2700, ARCH_PASCAL_SLOT_WORD(s));
}

/* Only the low 16 bits of a wider value travel (a Pascal word). */
static void test_word_slot_truncates(void)
{
    ASSERT_EQ(0x56780000u, ARCH_PASCAL_WORD_SLOT(0x12345678u));
    ASSERT_EQ(0xFFFF0000u, ARCH_PASCAL_WORD_SLOT((int16_t)-1));
}

/* A byte parameter (MMU_$SET_CSR `move.b (5,sp)') is the low byte of the
 * first word: the second byte of the big-endian slot. */
static void test_byte_in_word_slot(void)
{
    uint8_t b[4];

    be_bytes(ARCH_PASCAL_WORD_SLOT((uint8_t)0xA5), b);
    ASSERT_EQ(0x00, b[0]);
    ASSERT_EQ(0xA5, b[1]);
}

/* f(a.w, b.w): pushed b then a, so a is at the lower address. */
static void test_pair_slot_order(void)
{
    uint8_t b[4];
    uint32_t s = ARCH_PASCAL_WORD_PAIR_SLOT(0x1234, 0xABCD);

    ASSERT_EQ(0x1234ABCDu, s);
    be_bytes(s, b);
    ASSERT_EQ(0x12, b[0]);
    ASSERT_EQ(0x34, b[1]);
    ASSERT_EQ(0xAB, b[2]);
    ASSERT_EQ(0xCD, b[3]);
    ASSERT_EQ(0x1234, ARCH_PASCAL_SLOT_WORD(s));
    ASSERT_EQ(0xABCD, ARCH_PASCAL_SLOT_WORD2(s));
    /* MMU_$INSTALL's `pea (0x16).w' is the pair asid 0, prot 0x16 */
    ASSERT_EQ(0x00000016u, ARCH_PASCAL_WORD_PAIR_SLOT(0, 0x16));
}

/* (4) w.w, (6) l.l unpadded: l straddles two slots. */
static void test_straddled_long(void)
{
    uint32_t s1 = ARCH_PASCAL_WORD_PAIR_SLOT(0x001D, 0x00E0A400u >> 16);
    uint32_t s2 = ARCH_PASCAL_WORD_SLOT(0x00E0A400u);
    uint8_t b[8];

    be_bytes(s1, b);
    be_bytes(s2, b + 4);
    /* the Pascal frame bytes: 00 1D | 00 E0 A4 00 | pad */
    ASSERT_EQ(0x00, b[0]);
    ASSERT_EQ(0x1D, b[1]);
    ASSERT_EQ(0x00, b[2]);
    ASSERT_EQ(0xE0, b[3]);
    ASSERT_EQ(0xA4, b[4]);
    ASSERT_EQ(0x00, b[5]);
    ASSERT_EQ(0x00E0A400u, ARCH_PASCAL_SLOTS_LONG(s1, s2));
}

static void test_spin_unlock_macro(void)
{
    static uint32_t lock;

    unlock_calls = 0;
    ML_$SPIN_UNLOCK(&lock, (ml_$spin_token_t)0x2004);
    ASSERT_EQ(1, unlock_calls);
    ASSERT_EQ((uintptr_t)&lock, (uintptr_t)unlock_lockp);
    ASSERT_EQ(0x2004, unlock_token);
}

static void test_install_macro(void)
{
    MMU_$INSTALL(0x123, 0xFF8C00, 0x2A, 0x16);
    ASSERT_EQ(0x123, install_ppn);
    ASSERT_EQ(0xFF8C00, install_va);
    ASSERT_EQ(0x2A, install_asid);
    ASSERT_EQ(0x16, install_prot);
}

static void test_trap_macro(void)
{
    static uint8_t window[0x100];

    ARCH_HOST_VA_BASE = (uintptr_t)window;
    IO_$TRAP(0x1B, window + 0x40);
    ARCH_HOST_VA_BASE = 0;
    ASSERT_EQ(0x1B, trap_vector);
    ASSERT_EQ(0x40, trap_handler_va);
}

int main(void)
{
    printf("Running Pascal parameter slot tests...\n");
    RUN_TEST(test_word_slot_is_first_word);
    RUN_TEST(test_word_slot_truncates);
    RUN_TEST(test_byte_in_word_slot);
    RUN_TEST(test_pair_slot_order);
    RUN_TEST(test_straddled_long);
    RUN_TEST(test_spin_unlock_macro);
    RUN_TEST(test_install_macro);
    RUN_TEST(test_trap_macro);
    if (failures) {
        printf("%d FAILED\n", failures);
        return 1;
    }
    printf("All tests PASSED\n");
    return 0;
}
